-- BattleBallServer: boss groups, boss templates, dungeons. GENERATED by BattleBall/SourceData/tools/build_dungeon_seed_sql.py.
-- Status: PROPOSED structure; the dungeon -> boss group choice is CONFIRMED (owner, 2026-10-07, boss_group_picker.html).
-- Boss names, outfits and NRO hp/dame come from the NRO boss code (read-only reference). BattleBall boss stats are NOT stored here (OPEN):
-- they follow GDD section 7 by dungeon tier and boss role. All roles are NORMAL because the owner did not mark mini/final bosses yet.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS boss_group (
  group_key  VARCHAR(40)  NOT NULL,                  -- folder name of the NRO boss code, or a BattleBall group (hoa_khi_xayda)
  label_vi   VARCHAR(120) NOT NULL,
  tag        ENUM('DUNGEON','BOSS','MOB','SPECIAL','EVENT') NOT NULL,   -- MOB = small mobs that swarm during fights
  enabled    TINYINT(1)   NOT NULL DEFAULT 1,
  updated_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by VARCHAR(64)  NULL,
  PRIMARY KEY (group_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS boss_template (
  boss_id    INT UNSIGNED NOT NULL,
  group_key  VARCHAR(40)  NOT NULL,
  name_vi    VARCHAR(120) NOT NULL,
  race       ENUM('EARTH','NAMEC','XAYDA') NULL,
  part_head  INT NOT NULL,                           -- client part ids (head, body, leg), -1 = none; drawn like a skin
  part_body  INT NOT NULL,
  part_leg   INT NOT NULL,
  nro_hp     BIGINT UNSIGNED NULL,                   -- reference only (NRO values)
  nro_dame   INT UNSIGNED NULL,
  enabled    TINYINT(1)   NOT NULL DEFAULT 1,
  note       VARCHAR(255) NULL,
  updated_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by VARCHAR(64)  NULL,
  PRIMARY KEY (boss_id),
  KEY idx_boss_group (group_key),
  CONSTRAINT fk_boss_group FOREIGN KEY (group_key) REFERENCES boss_group (group_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dungeon_template (
  dungeon_id INT UNSIGNED NOT NULL,
  name_vi    VARCHAR(120) NOT NULL,
  tier       ENUM('early','mid','late') NOT NULL,    -- GDD section 7 zone tier: early / mid / late
  group_key  VARCHAR(40)  NULL,                      -- one boss group per dungeon, each group used by at most one dungeon
  enabled    TINYINT(1)   NOT NULL DEFAULT 1,
  note       VARCHAR(255) NULL,
  sort_order SMALLINT     NOT NULL DEFAULT 0,
  updated_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by VARCHAR(64)  NULL,
  PRIMARY KEY (dungeon_id),
  UNIQUE KEY uq_dungeon_group (group_key),
  CONSTRAINT fk_dungeon_group FOREIGN KEY (group_key) REFERENCES boss_group (group_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dungeon_boss (
  dungeon_id INT UNSIGNED NOT NULL,
  boss_id    INT UNSIGNED NOT NULL,
  role       ENUM('NORMAL','MINI','FINAL','MINION') NOT NULL DEFAULT 'NORMAL',  -- mini-boss of a floor / final boss / small mob that spawns en masse
  sort_order SMALLINT     NOT NULL DEFAULT 0,
  updated_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by VARCHAR(64)  NULL,
  PRIMARY KEY (dungeon_id, boss_id),
  CONSTRAINT fk_dboss_dungeon FOREIGN KEY (dungeon_id) REFERENCES dungeon_template (dungeon_id) ON DELETE CASCADE,
  CONSTRAINT fk_dboss_boss    FOREIGN KEY (boss_id)    REFERENCES boss_template (boss_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;





